Algorithm Triangle
  Define a As Integer;
  Define b As Integer;
  Define c As Integer;
  Read a;
  Read b;
  Read c;
  If a >= b + c Or b >= a + c Or c >= a + b Then
    Write "not a triangle";
  Else
    If a = b And b = c Then
      Write "equilateral";
    Else
      If a = b Or b = c Or a = c Then
        Write "isosceles";
      Else
        Write "scalene";
      EndIf
    EndIf
  EndIf
EndAlgorithm
